var e=(e,{database:a})=>{e.get("/:giveawayId",async(e,r,t)=>{try{const{giveawayId:t}=e.params,n=await a("giveaways").select("enable_leaderboard","leaderboard_start_date","leaderboard_prizes").where("id",t).first();if(!n)return r.status(404).json({success:!1,error:"Giveaway not found"});if(!n.enable_leaderboard)return r.json({success:!0,data:[]});let s=a("tickets").select("client_name").count("id as count").where("giveaway_id",t).groupBy("client_name").orderBy("count","desc").limit(10);n.leaderboard_start_date&&(s=s.where("date_created",">=",n.leaderboard_start_date));const d=(await s).map(e=>({name:e.client_name||"Unknown",count:Number(e.count)})).filter(e=>"Unknown"!==e.name);return r.json({success:!0,data:d,prizes:n.leaderboard_prizes||null})}catch(e){return console.error("Leaderboard error:",e),t(e)}})};export{e as default};
